// Run inside the browser on the page generated by nfn-fixture.mjs.
(async () => {
  const checks = [];
  const assert = (condition, label) => { if (!condition) throw new Error(label); checks.push(label); };
  const sleep = ms => new Promise(resolve => setTimeout(resolve, ms));
  const buttons = () => [...document.querySelectorAll("button")];
  window.nfn.collapse();
  window.fixture.calls.length = 0; window.fixture.contextCalls = 0;
  window.fixture.records.clear();
  window.fixture.records.set("first", window.fixture.record("first"));
  window.nfn.receive(window.fixture.snapshot("first"));
  assert(document.querySelectorAll(".actions button").length === 3, "compact cards expose three choices");
  assert(!window.unsafeMarkup && !document.querySelector(".body img"), "request text cannot inject markup");
  document.querySelector("#surface").dispatchEvent(new MouseEvent("mouseenter"));
  const second = window.fixture.record("second"); second.request.title = "Second request"; second.request.source.task = "Second request";
  window.fixture.records.set("second", second); window.nfn.receive(window.fixture.snapshot("second"));
  assert(document.querySelector("h1").textContent === "Review the launch post", "new arrivals preserve the current card");
  buttons().find(b => b.textContent.startsWith("Expand")).click(); await sleep(60);
  assert(document.querySelectorAll(".actions button").length === 4, "expansion exposes additional choices");
  const input = document.querySelector("textarea"); input.value = "Keep this draft"; input.dispatchEvent(new Event("input"));
  const scroller = document.querySelector(".expanded-content"); scroller.scrollTop = 30;
  window.nfn.receive(window.fixture.snapshot()); await sleep(30);
  assert(document.querySelector("textarea") === input && input.value === "Keep this draft", "snapshot updates preserve input and draft");
  window.fixture.records.get("first").request.body = "Updated caption for review";
  window.nfn.receive(window.fixture.snapshot()); await sleep(30);
  assert(document.querySelector(".body").textContent === "Updated caption for review" && document.querySelector("textarea").value === "Keep this draft", "deduplicated payload updates preserve drafts");
  assert(document.querySelector(".row .diff-add"), "nested row layouts render diff primitives");
  const content = [...document.querySelector(".expanded-content").children];
  assert(content.indexOf(document.querySelector(".reply")) < content.indexOf(document.querySelector(".actions")), "custom layout order is respected");
  buttons().find(b => b.textContent === "Send reply").click(); buttons().find(b => b.textContent === "Send reply").click(); await sleep(60);
  assert(window.fixture.calls.filter(c => c.op === "respond").length === 1, "duplicate response clicks dispatch once");
  assert(document.querySelector("textarea").disabled || document.querySelector(".reply button").disabled, "resolved cards disable submission");
  window.nfn.collapse(); const calls = window.fixture.contextCalls; await sleep(1150);
  assert(window.fixture.contextCalls === calls, "collapsed cards stop log polling");
  window.fixture.records.get("first").status = "pending";
  for (let i = 0; i < 65; i++) window.fixture.records.set(`burst-${i}`, window.fixture.record(`burst-${i}`));
  window.nfn.receive(window.fixture.snapshot()); window.nfn.receive({ type: "show" });
  assert(document.querySelectorAll(".queue-item").length === 50, "pending queue loads a bounded page");
  buttons().find(b => b.textContent === "Load more").click(); await sleep(60);
  assert(document.querySelectorAll(".queue-item").length === 67, "pending queue paginates beyond fifty requests");
  window.nfn.receive({ ...window.fixture.snapshot(), preview: true });
  document.querySelector(".queue-item").click(); await sleep(30);
  const responses = window.fixture.calls.filter(c => c.op === "respond").length;
  document.querySelector(".actions button").click(); await sleep(30);
  assert(window.fixture.calls.filter(c => c.op === "respond").length === responses, "preview actions never dispatch real responses");
  window.nfn.collapse();
  document.querySelector("#surface").dispatchEvent(new MouseEvent("mouseleave"));
  window.fixture.records.get("first").request.media = [{ kind: "video", src: "/tmp/clawtab-nfn-media-test.mp4" }];
  const mediaSnapshot = window.fixture.snapshot("first"); mediaSnapshot.templates.templates[0].layout.unshift({ type: "media" });
  window.nfn.receive(mediaSnapshot);
  assert(!document.querySelector("video"), "compact cards do not load video");
  buttons().find(b => b.textContent.startsWith("Expand")).click();
  const video = document.querySelector("video");
  assert(video && video.preload === "metadata", "video loads lazily in expanded cards");
  window.nfn.collapse();
  assert(video.paused && !video.hasAttribute("src"), "closing a card releases its video source");
  return { passed: checks.length, checks };
})()
